using System;public class Solution{public int MaxKilledEnemies(char[][]g){if(g.Length==0)return 0;int m=g.Length,n=g[0].Length,row=0,b=0;int[]c=new int[n];for(int i=0;i<m;i++)for(int j=0;j<n;j++){if(j==0||g[i][j-1]=='W'){row=0;for(int k=j;k<n&&g[i][k]!='W';k++)if(g[i][k]=='E')row++;}if(i==0||g[i-1][j]=='W'){c[j]=0;for(int k=i;k<m&&g[k][j]!='W';k++)if(g[k][j]=='E')c[j]++;}if(g[i][j]=='0')b=Math.Max(b,row+c[j]);}return b;}}
